solution.code:
export const guia = {
  filas: [
    { amenaza: "Minería de criptomonedas no autorizada en instancias EC2", servicio: "Amazon GuardDuty" },
    { amenaza: "Vulnerabilidades de software en instancias EC2, imágenes de ECR y funciones Lambda", servicio: "Amazon Inspector" },
    { amenaza: "Datos sensibles en buckets de Amazon S3", servicio: "Amazon Macie" },
    { amenaza: "Peticiones HTTP(S) que hay que bloquear según su IP de origen", servicio: "AWS WAF" },
    { amenaza: "Ataques DDoS volumétricos como las inundaciones TCP SYN", servicio: "AWS Shield" },
    { amenaza: "Vista única de hallazgos de varios servicios de seguridad", servicio: "AWS Security Hub" },
  ],
};

spec.code:
const fila = guia.filas.find((f) => f.amenaza.startsWith("Peticiones HTTP(S)"));
assert.ok(fila, "debe existir la fila de las peticiones HTTP(S)");
assert.strictEqual(fila.servicio, "AWS WAF");

const validos = ["Amazon GuardDuty", "Amazon Inspector", "AWS Security Hub", "AWS Shield", "AWS WAF", "Amazon Macie"];
for (const fila of guia.filas) {
  assert.ok(validos.includes(fila.servicio), fila.amenaza + " tiene un servicio no válido");
}

const esperado = {
  "Minería de criptomonedas no autorizada en instancias EC2": "Amazon GuardDuty",
  "Vulnerabilidades de software en instancias EC2, imágenes de ECR y funciones Lambda": "Amazon Inspector",
  "Datos sensibles en buckets de Amazon S3": "Amazon Macie",
  "Ataques DDoS volumétricos como las inundaciones TCP SYN": "AWS Shield",
  "Vista única de hallazgos de varios servicios de seguridad": "AWS Security Hub",
};
for (const [amenaza, servicio] of Object.entries(esperado)) {
  const fila = guia.filas.find((f) => f.amenaza === amenaza);
  assert.ok(fila, amenaza + " debe seguir existiendo");
  assert.strictEqual(fila.servicio, servicio);
}

