// Devuelve los hallazgos más graves de un panel unificado. Corrige su defecto principal.
export type Hallazgo = { servicio: string; recurso: string; gravedad: number };

export function hallazgosPrioritarios(hallazgos: Hallazgo[], maximo: number): Hallazgo[] {
  return hallazgos.sort((a, b) => b.gravedad - a.gravedad).slice(0, maximo);
}

solution.code:
export type Hallazgo = { servicio: string; recurso: string; gravedad: number };

export function hallazgosPrioritarios(hallazgos: Hallazgo[], maximo: number): Hallazgo[] {
  return [...hallazgos].sort((a, b) => b.gravedad - a.gravedad).slice(0, maximo);
}

spec.code:
const lista: Hallazgo[] = [
  { servicio: "Amazon Inspector", recurso: "i-01", gravedad: 2 },
  { servicio: "Amazon GuardDuty", recurso: "i-02", gravedad: 4 },
  { servicio: "Amazon Macie", recurso: "b-01", gravedad: 3 },
  { servicio: "Amazon Inspector", recurso: "i-03", gravedad: 1 },
];
assert.deepStrictEqual(hallazgosPrioritarios(lista, 2).map((h) => h.recurso), ["i-02", "b-01"]);

const lista: Hallazgo[] = [
  { servicio: "Amazon Inspector", recurso: "i-01", gravedad: 2 },
  { servicio: "Amazon GuardDuty", recurso: "i-02", gravedad: 4 },
  { servicio: "Amazon Macie", recurso: "b-01", gravedad: 3 },
  { servicio: "Amazon Inspector", recurso: "i-03", gravedad: 1 },
];
hallazgosPrioritarios(lista, 2);
assert.deepStrictEqual(lista.map((h) => h.recurso), ["i-01", "i-02", "b-01", "i-03"]);

const lista: Hallazgo[] = [
  { servicio: "Amazon Inspector", recurso: "i-01", gravedad: 2 },
  { servicio: "Amazon GuardDuty", recurso: "i-02", gravedad: 4 },
  { servicio: "Amazon Macie", recurso: "b-01", gravedad: 3 },
  { servicio: "Amazon Inspector", recurso: "i-03", gravedad: 1 },
];
const todos = hallazgosPrioritarios(lista, 10);
assert.deepStrictEqual(todos.map((h) => h.recurso), ["i-02", "b-01", "i-01", "i-03"]);
assert.deepStrictEqual(lista.map((h) => h.recurso), ["i-01", "i-02", "b-01", "i-03"]);

const lista: Hallazgo[] = [
  { servicio: "Amazon Inspector", recurso: "i-01", gravedad: 2 },
  { servicio: "Amazon GuardDuty", recurso: "i-02", gravedad: 4 },
  { servicio: "Amazon Macie", recurso: "b-01", gravedad: 3 },
  { servicio: "Amazon Inspector", recurso: "i-03", gravedad: 1 },
];
const primera = hallazgosPrioritarios(lista, 3).map((h) => h.recurso);
const segunda = hallazgosPrioritarios(lista, 3).map((h) => h.recurso);
assert.deepStrictEqual(primera, segunda);
assert.strictEqual(lista[0].recurso, "i-01");

const lista: Hallazgo[] = [
  { servicio: "Amazon Inspector", recurso: "i-01", gravedad: 2 },
  { servicio: "Amazon GuardDuty", recurso: "i-02", gravedad: 4 },
  { servicio: "Amazon Macie", recurso: "b-01", gravedad: 3 },
  { servicio: "Amazon Inspector", recurso: "i-03", gravedad: 1 },
];
assert.deepStrictEqual(hallazgosPrioritarios(lista, 0), []);
assert.strictEqual(lista.length, 4);
